import numpy as np
S=np.diag([1.0, 4.0]);M=np.eye(2);K=np.diag([-1.0, 2.0])
c=np.arange(2);sig=np.ones(2);R=np.eye(2);D=np.ones((2,2))-np.eye(2)

def _pack_result(value):
    mu,rho,action=value
    return np.concatenate((np.array([mu,*rho.shape,*action.shape],dtype=float),rho.ravel(),action.ravel()))

def _finite_call(fun):
    with np.errstate(over="raise",invalid="raise",divide="raise",under="ignore"):
        result=fun()
    if not np.all(np.isfinite(result)):
        raise ValueError("nonfinite output")
    return result
assert np.allclose(_finite_call(lambda: _pack_result(solve_fixed_population_density(S,M,K,R,D,c,sig,40.0,1.0,1,1.0))), target)

